model:
rachana: 1
sutra: cnv-segment
version: 1
description: 
match: { kind: cnv-segment, priority: 10 }
title: { pill: "Genomics · Copy-number segment", id: "$.SEGMENT_ID" }
strip:
  - { label: "Segment id", bind: "$.SEGMENT_ID" }
  - { label: "Sample id", bind: "link($.SAMPLE_ID, 'study-sample')" }
  - { label: "Chrom", bind: "$.CHROM" }
  - { label: "Copy number", bind: "$.COPY_NUMBER", fmt: "amount0" }
  - { label: "Call", bind: "$.CALL", emphasis: true }
panels:
  - id: record
    kind: kv
    title: "Copy-number segment"
    columns:
      - { label: "Segment id", bind: "$.SEGMENT_ID" }
      - { label: "Sample id", bind: "link($.SAMPLE_ID, 'study-sample')" }
      - { label: "Chrom", bind: "$.CHROM" }
      - { label: "Start", bind: "$.START", fmt: "amount0" }
      - { label: "End", bind: "$.END", fmt: "amount0" }
      - { label: "Copy number", bind: "$.COPY_NUMBER", fmt: "amount0" }
      - { label: "Call", bind: "$.CALL" }
      - { label: "Gene", bind: "link($.GENE, 'study-gene')" }
keys: { F9: "raw" }
